 pub struct Foo {
     // ..
 }

 impl Foo {
     pub fn new() -> Self {
         // setup here ..
     }

     pub unsafe fn parts() -> (&str, &str) {
         // assumes invariants hold
     }
 }
 ```
" in static UNSAFE_DERIVE_DESERIALIZE_INFO

