     fn eq(&self, b: &Self) -> bool {
         self.0 == b.0
     }
 }
 ```
 Use instead:
 ```rust
 struct A(u32);

 impl PartialEq for A {
     fn eq(&self, other: &Self) -> bool {
         self.0 == other.0
     }
 }
 ```
" in static RENAMED_FUNCTION_PARAMS_INFO

