 let f: option::IntoIter<i32> = None.into_iter();
 ```
 Use instead:
 ```no_run
 use std::iter;
 let a: iter::Empty<i32> = iter::empty();
 let b: iter::Empty<i32> = iter::empty();
 ```

 ### Known problems

 The type of the resulting iterator might become incompatible with its usage
