     // code
 }
 ```
 Use instead:
 ```no_run
 # use std::collections::HashSet;
 let s: HashSet<String> = HashSet::new();
 if s.contains("a") {
     // code
 }
 ```
" in static UNNECESSARY_GET_THEN_CHECK_INFO

