     I32,
     I64,
     F32,
     F64,
 }

 impl ValType {
     pub fn bytes(self) -> usize {
         match self {
             Self::I32 | Self::F32 => 4,
             Self::I64 | Self::F64 => 8,
         }
     }
 }
 ```
" in static NEEDLESS_ARBITRARY_SELF_TYPE_INFO

